module fsm_3state (
    input clk, reset,
    output reg [1:0] state
);

    parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10;
    reg [1:0] next_state;

    always @(posedge clk or posedge reset) begin
        if (reset) 
            state <= S0;
        else 
            state <= next_state;
    end

    always @(*) begin
        case (state)
            S0: next_state = S1;
            S1: next_state = S2;
            S2: next_state = S0;
            default: next_state = S0;
        endcase
    end

endmodule

