module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    reg [1:0] current_state, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= 2'b00;
        else
            current_state <= next_state;
    end

    always @(current_state) begin
        case (current_state)
            2'b00: next_state = 2'b01; // Transition from state 0 to state 1
            2'b01: next_state = 2'b10; // Transition from state 1 to state 2
            2'b10: next_state = 2'b00; // Transition from state 2 back to state 0
            default: next_state = 2'b00; // Default to state 0
        endcase
    end

    assign state = current_state;
endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);
    reg [2:0] state;
    parameter RED = 3'b001, GREEN = 3'b010, YELLOW = 3'b100;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= RED;
        end else begin
            case (state)
                RED: state <= GREEN;
                GREEN: state <= YELLOW;
                YELLOW: state <= RED;
                default: state <= RED;
            endcase
        end
    end

    assign light = state;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output reg [1:0] state
);
    parameter IDLE = 2'b00, UP = 2'b01, DOWN = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (up_request) 
                        state <= UP;
                    else if (down_request) 
                        state <= DOWN;
                end
                UP: begin
                    if (down_request) 
                        state <= DOWN;
                    else if (!up_request) 
                        state <= IDLE;
                end
                DOWN: begin
                    if (up_request) 
                        state <= UP;
                    else if (!down_request) 
                        state <= IDLE;
                end
            endcase
