module pipelined_fir (
    input clk, rst,
    input [7:0] x,
    output reg [15:0] y
);
    reg [7:0] coeff [0:3]; // Coefficients for the FIR filter
    reg [7:0] x_reg [0:3]; // Delay line for input samples
    integer i;

    initial begin
        coeff[0] = 8'd1; // Example coefficients
        coeff[1] = 8'd2;
        coeff[2] = 8'd3;
        coeff[3] = 8'd4;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y <= 16'd0;
            for (i = 0; i < 4; i = i + 1) begin
                x_reg[i] <= 8'd0;
            end
        end else begin
            // Shift input samples
            x_reg[3] <= x_reg[2];
            x_reg[2] <= x_reg[1];
            x_reg[1] <= x_reg[0];
            x_reg[0] <= x;

            // Compute FIR output
            y <= (coeff[0] * x_reg[0]) +
                 (coeff[1] * x_reg[1]) +
                 (coeff[2] * x_reg[2]) +
                 (coeff[3] * x_reg[3]);
        end
    end
endmodule

