    reg [15:0] y_reg [0:4]; // Output registers for each stage
    integer i;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < 5; i = i + 1) begin
                x_reg[i] <= 0;
                y_reg[i] <= 0;
            end
            y <= 0;
        end else begin
            x_reg[0] <= x; // Input to first stage
            for (i = 1; i < 5; i = i + 1) begin
                x_reg[i] <= x_reg[i-1]; // Shift input through pipeline
