module gradient_descent (
    input signed [31:0] in_0,
    input signed [31:0] in_1,
    input signed [31:0] in_2,
    output signed [31:0] out);

    // Parameters for learning rate and maximum iterations
    parameter signed [31:0] LEARNING_RATE = 32'h00000001; // Adjust as needed
    parameter integer MAX_ITERATIONS = 32;

    // Internal registers
    reg signed [31:0] current_value;
    reg signed [31:0] gradient;
    integer i;

    // Initial value
    initial begin
        current_value = in_0; // Start from the initial input
    end

    always @* begin
