        else if (data_in >= 8'h61 && data_in <= 8'h7A) // a-z
            temp = ((data_in - 8'h61 + 3) % 26) + 8'h61;
        else
            temp = data_in; // Non-alphabetic characters remain unchanged
    end

    assign data_out = temp;
