module heat_index (
    input [7:0] temperature,   // Temperature in Celsius
    input [7:0] humidity,      // Humidity in percentage
    input signed [15:0] C1, C2, C3, C4, C5, C6, C7, C8, C9,    // Quartic T^2*R^2
    output signed [15:0] heat_index // Heat Index in Celsius
);

    wire signed [15:0] T;
    wire signed [15:0] R;
    wire signed [15:0] T2;
    wire signed [15:0] R2;
    wire signed [15:0] HI;

    assign T = temperature;
    assign R = humidity;
    assign T2 = T * T;
    assign R2 = R * R;

    assign HI = C1 + (C2 * T) + (C3 * R) + (C4 * T * R) + (C5 * T2) + (C6 * R2) + (C7 * T * R2) + (C8 * T2 * R) + (C9 * T2 * R2);

    assign heat_index = HI;

endmodule

