module air_quality_index (
    input [7:0] pm2_5,
    input [7:0] pm10,
    input [7:0] no2,
    output reg [15:0] aqi
);

always @(*) begin
    reg [15:0] aqi_pm2_5, aqi_pm10, aqi_no2;

    // Calculate AQI for PM2.5
    if (pm2_5 <= 12) 
        aqi_pm2_5 = pm2_5 * 5;
    else if (pm2_5 <= 35)
        aqi_pm2_5 = 25 + (pm2_5 - 12) * 10 / 23;
    else if (pm2_5 <= 55)
        aqi_pm2_5 = 50 + (pm2_5 - 35) * 10 / 20;
    else if (pm2_5 <= 150)
        aqi_pm2_5 = 100 + (pm2_5 - 55) * 100 / 95;
    else if (pm2_5 <= 250)
        aqi_pm2_5 = 200 + (pm2_5 - 150) * 100 / 100;
    else if (pm2_5 <= 500)
        aqi_pm2_5 = 300 + (pm2_5 - 250) * 100 / 250;
    else
        aqi_pm2_5 = 500;

    // Calculate AQI for PM10
    if (pm10 <= 54) 
        aqi_pm10 = pm10 * 5;
    else if (pm10 <= 154)
        aqi_pm10 = 25 + (pm10 - 54) * 10 / 100;
    else if (pm10 <= 254)
        aqi_pm10 = 50 + (pm10 - 154) * 100 / 100;
    else if (pm10 <= 354)
        aqi_pm10 = 100 + (pm10 - 254) * 100 / 100;
    else if (pm10 <= 424)
        aqi_pm10 = 200 + (pm10 - 354) * 100 / 70;
    else if (pm10 <= 604)
        aqi_pm10 = 300 + (pm10 - 424) * 100 / 180;
    else
        aqi_pm10 = 500;

    // Calculate AQI for NO2
    if (no2 <= 53) 
        aqi_no2 = no2 * 5;
    else if (no2 <= 100)
        aqi_no2 = 25 + (no2 - 53) * 10 / 47;
    else if (no2 <= 360)
        aqi_no2 = 50 + (no2 - 100) * 100 / 260;
    else if (no2 <= 649)
        aqi_no2 = 100 + (no2 - 360) * 100 / 289;
    else if (no2 <= 1249)
        aqi_no2 = 200 + (no2 - 649) * 100 / 700;
    else
        aqi_no2 = 500;

    // Select the maximum AQI
    aqi = (aqi_pm2_5 > aqi_pm10) ? (aqi_pm2_5 > aqi_no2 ? aqi_pm2_5 : aqi_no2) : (aqi_pm10 > aqi_no2 ? aqi_pm10 : aqi_no2);
end

endmodule

