        aqi_pm2_5 = (pm2_5 * 50) / 12;
    else if (pm2_5 <= 35)
        aqi_pm2_5 = ((pm2_5 - 12) * 50 / 23) + 51;
    else if (pm2_5 <= 55)
        aqi_pm2_5 = ((pm2_5 - 35) * 50 / 20) + 101;
    else if (pm2_5 <= 150)
        aqi_pm2_5 = ((pm2_5 - 55) * 50 / 95) + 151;
    else if (pm2_5 <= 250)
        aqi_pm2_5 = ((pm2_5 - 150) * 50 / 100) + 201;
    else 
        aqi_pm2_5 = 301;

    // Calculate AQI for PM10
    if (pm10 <= 54) 
        aqi_pm10 = (pm10 * 50) / 54;
    else if (pm10 <= 154)
        aqi_pm10 = ((pm10 - 54) * 50 / 100) + 51;
    else if (pm10 <= 254)
        aqi_pm10 = ((pm10 - 154) * 50 / 100) + 151;
    else if (pm10 <= 354)
        aqi_pm10 = ((pm10 - 254) * 50 / 100) + 201;
