        aqi_no2 = ((no2 - 100) * 50 / 80) + 101;
    else if (no2 <= 280)
        aqi_no2 = ((no2 - 180) * 50 / 100) + 151;
    else 
        aqi_no2 = 301;

    // Determine the highest AQI value
