        aqi_value = 50 + (pm2_5 - 12) * 10 / 2;
    else if (pm2_5 <= 55) 
        aqi_value = 100 + (pm2_5 - 35) * 10 / 2;
    else if (pm2_5 <= 150) 
        aqi_value = 150 + (pm2_5 - 55) * 10 / 5;
    else 
        aqi_value = 200 + (pm2_5 - 150) * 10 / 10;

    if (pm10 <= 54) 
        aqi_value = (aqi_value > pm10 * 10) ? aqi_value : pm10 * 10;
    else if (pm10 <= 154) 
        aqi_value = (aqi_value > 50 + (pm10 - 54) * 10 / 2) ? aqi_value : 50 + (pm10 - 54) * 10 / 2;
    else if (pm10 <= 254) 
        aqi_value = (aqi_value > 100 + (pm10 - 154) * 10 / 5) ? aqi_value : 100 + (pm10 - 154) * 10 / 5;
    else 
        aqi_value = (aqi_value > 200 + (pm10 - 254) * 10 / 10) ? aqi_value : 200 + (pm10 - 254) * 10 / 10;

    if (no2 <= 53) 
        aqi_value = (aqi_value > no2 * 10) ? aqi_value : no2 * 10;
    else if (no2 <= 100) 
        aqi_value = (aqi_value > 50 + (no2 - 53) * 10 / 2) ? aqi_value : 50 + (no2 - 53) * 10 / 2;
    else if (no2 <= 360) 
        aqi_value = (aqi_value > 100 + (no2 - 100) * 10 / 5) ? aqi_value : 100 + (no2 - 100) * 10 / 5;
    else 
        aqi_value = (aqi_value > 200 + (no2 - 360) * 10 / 10) ? aqi_value : 200 + (no2 - 360) * 10 / 10;
end

assign aqi = aqi_value;

